<script setup>
import { ref, onMounted } from 'vue';
import { api, send, isAdmin, loadSession } from './api';
const members=ref([]),q=ref(''),offset=ref(0),error=ref(''),busy=ref(false);
async function search(next=false){if(!next)offset.value=0;busy.value=true;error.value='';try{const batch=await api('/admin/members?q='+encodeURIComponent(q.value)+'&after='+offset.value);members.value=next?[...members.value,...batch]:batch;offset.value+=batch.length;}catch(e){error.value=e.message;}finally{busy.value=false;}}
async function change(m,role){busy.value=true;try{await send('/admin/members/'+encodeURIComponent(m.id)+'/'+role.toLowerCase(),{enabled:!m.roles.includes(role)},'PUT');await loadSession();await search();}catch(e){error.value=e.message;}finally{busy.value=false;}}
onMounted(()=>{if(isAdmin())search();});
</script>
<template><div v-if="!isAdmin()" class="card"><h1>Administrator access required.</h1></div><template v-else><div class="page-heading"><div><p class="eyebrow">CONTROLLED ACCESS</p><h1>The right people<span class="lime-dot">.</span></h1><p>Manage coach and supervisor access. Accounts share one sign-in and receive only the permissions you approve.</p></div></div><section class="card"><form class="search-row" @submit.prevent="search()"><label>Find a member by email<input v-model="q" type="search" maxlength="100"></label><button :disabled="busy">Search</button></form><p v-if="error" class="error" role="alert">{{error}}</p><div class="table-scroll"><table><thead><tr><th>Member</th><th>Email</th><th>Access</th><th>Action</th></tr></thead><tbody><tr v-for="m in members" :key="m.id"><td>{{m.displayName||'Member'}}</td><td>{{m.email}}</td><td>{{m.roles.map(x=>x==='Supervisor'?'Coach supervisor':x).join(', ')||'Athlete'}}</td><td><div class="actions"><button class="secondary" :disabled="busy" @click="change(m,'Coach')">{{m.roles.includes('Coach')?'Remove coach':'Approve coach'}}</button><button class="secondary" :disabled="busy" @click="change(m,'Supervisor')">{{m.roles.includes('Supervisor')?'Remove supervisor':'Approve supervisor'}}</button></div></td></tr></tbody></table></div><button v-if="members.length&&members.length%30===0" class="text-button" :disabled="busy" @click="search(true)">Load more members</button><p class="hint">Assign approved coaches to a supervisor in Coaching team. System administrator access is provisioned privately; it cannot be granted through public registration.</p></section></template></template>
